{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Document Review Findings",
  "description": "Structured output schema for document review persona agents",
  "type": "object",
  "required": ["reviewer", "findings", "residual_risks", "deferred_questions"],
  "properties": {
    "reviewer": {
      "type": "string",
      "description": "Persona name that produced this output (e.g., 'coherence', 'feasibility', 'product-lens')"
    },
    "findings": {
      "type": "array",
      "description": "List of document review findings. Empty array if no issues found.",
      "items": {
        "type": "object",
        "required": [
          "title",
          "severity",
          "section",
          "why_it_matters",
          "finding_type",
          "autofix_class",
          "confidence",
          "evidence"
        ],
        "properties": {
          "title": {
            "type": "string",
            "description": "Short, specific issue title. 10 words or fewer.",
            "maxLength": 100
          },
          "severity": {
            "type": "string",
            "enum": ["P0", "P1", "P2", "P3"],
            "description": "Issue severity level"
          },
          "section": {
            "type": "string",
            "description": "Document section where the issue appears, named so a reader who does not have the document open can tell what it is. Give the identifier a short handle on first mention: 'U1 - Establish profile contracts', not 'U1'. Plain section names that need no handle are fine as-is (e.g., 'Requirements Trace', 'Overview')."
          },
          "why_it_matters": {
            "type": "string",
            "description": "Impact statement -- not 'what is wrong' but 'what goes wrong if not addressed'"
          },
          "autofix_class": {
            "type": "string",
            "enum": ["safe_auto", "gated_auto", "manual"],
            "description": "How this issue should be handled. safe_auto = one clear correct fix, mechanical enough that stating it and doing it are the same act (typo, wrong count, stale cross-reference, mechanically-implied addition, terminology drift). gated_auto = concrete fix that touches document meaning or scope, with no genuine alternative to it (substantive additions from codebase-pattern-resolved fixes, framework-native-API substitutions, missing standard controls). manual = requires user judgment; multiple valid approaches. Low-confidence manual findings surface in an FYI subsection at the presentation layer."
          },
          "finding_type": {
            "type": "string",
            "enum": ["error", "omission"],
            "description": "Whether the finding is a mistake in what the document says (error) or something the document forgot to say (omission). Errors are design tensions, contradictions, or incorrect statements. Omissions are missing mechanical steps, forgotten list entries, or absent details."
          },
          "suggested_fix": {
            "type": ["string", "null"],
            "description": "Concrete fix text. Omit or null if no good fix is obvious -- a bad suggestion is worse than none."
          },
          "confidence": {
            "type": "integer",
            "enum": [0, 25, 50, 75, 100],
            "description": "Anchored confidence score. Use exactly one of 0, 25, 50, 75, 100. Each anchor has a behavioral criterion the reviewer must honestly self-apply. 0: Not confident at all. This is a false positive that does not stand up to light scrutiny, or a pre-existing issue the document did not introduce. 25: Somewhat confident. Might be a real issue but could also be a false positive; the reviewer was not able to verify. 50: Moderately confident. The reviewer verified this is a real issue but it may be a nitpick or not meaningfully affect plan correctness. Relative to the rest of the document, it is not very important. Advisory observations (the honest answer to 'what breaks if we do not fix this?' is 'nothing breaks, but...') land here. 75: Highly confident. The reviewer double-checked and verified the issue will be hit in practice by implementers or readers of this document. The existing approach is insufficient. The issue is important and will directly impact plan correctness, implementer understanding, or downstream execution. 100: Absolutely certain. The reviewer double-checked and confirmed the issue. The evidence directly confirms it will happen frequently in practice. The document text, codebase, or cross-references leave no room for interpretation."
          },
          "evidence": {
            "type": "array",
            "description": "Quoted text from the document that supports this finding. At least 1 item.",
            "items": { "type": "string" },
            "minItems": 1
          }
        }
      }
    },
    "residual_risks": {
      "type": "array",
      "description": "Risks the reviewer noticed but could not confirm as findings (below confidence threshold)",
      "items": { "type": "string" }
    },
    "deferred_questions": {
      "type": "array",
      "description": "Questions that should be resolved in a later workflow stage (planning, implementation)",
      "items": { "type": "string" }
    }
  }
}

files.skills/ce-pov/references/pov-schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Cross-model point of view",
  "type": "object",
  "additionalProperties": false,
  "required": ["voice", "position", "reasoning", "evidence", "external_check", "mode", "movement", "final"],
  "properties": {
    "voice": {
      "type": "string",
      "minLength": 1,
      "description": "Short identity for the peer voice; the worker namespaces it to the provider."
    },
    "position": {
      "type": "string",
      "minLength": 1,
      "description": "The adoption grade, document or approach bottom line, skeptic verdict, or blocked state."
    },
    "reasoning": {
      "type": "string",
      "minLength": 1,
      "description": "Concise reasoning for the position, including the reason when blocked."
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "description": "A succinct claim with a URL, file:line, or named document section attribution."
      }
    },
    "external_check": {
      "type": "string",
      "enum": ["ran", "unavailable"]
    },
    "mode": {
      "type": "string",
      "enum": ["independent", "skeptic"]
    },
    "movement": {
      "type": "string",
      "enum": ["initial", "moved", "held"],
      "description": "Initial position, or whether the voice moved or held during reconciliation."
    },
    "final": {
      "type": "boolean",
      "description": "true when position is your settled answer (a settled Blocked verdict counts); false when you have not finished inspecting and position is a placeholder."
    },
    "cross_model_route": { "type": "string" },
    "cross_model_target": { "type": "string" },
    "cross_model_harness": { "type": "string" },
    "serving_family": { "type": "string" },
    "model_requested": { "type": "string" },
    "model_actual": { "type": "string" },
    "independence_verified": { "type": "boolean" }
  }
}

files.skills/ce-work/references/implementation:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://compound-engineering.dev/schemas/ce-work-implementation-result-v1.json",
  "title": "CE Work external implementation worker result",
  "type": "object",
  "required": [
    "terminal_status",
    "summary",
    "changed_files",
    "evidence",
    "scope_expansion"
  ],
  "properties": {
    "terminal_status": {
      "type": "string",
      "enum": ["completed", "blocked", "scope_expansion"]
    },
    "summary": {
      "type": "string",
      "minLength": 1
    },
    "changed_files": {
      "type": "array",
      "items": { "type": "string", "minLength": 1 },
      "uniqueItems": true
    },
    "evidence": {
      "type": "array",
      "items": { "type": "string", "minLength": 1 }
    },
    "scope_expansion": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "required": ["requested_paths", "reason"],
          "properties": {
            "requested_paths": {
              "type": "array",
              "items": { "type": "string", "minLength": 1 },
              "minItems": 1,
              "uniqueItems": true
            },
            "reason": { "type": "string", "minLength": 1 }
          },
          "additionalProperties": false
        }
      ]
    }
  },
  "additionalProperties": false
}
